const footerLinks = {
  about: [
    { label: "Our Mission", href: "/our-mission" },
    { label: "How It Works", href: "/how-it-works" },
    { label: "Portfolio", href: "/our-works" },
    { label: "Pricing", href: "/pricing" },
  ],
  services: [
    { label: "Web Development", href: "/services/website-development" },
    { label: "UI/UX Design", href: "/services/ui-ux-design", comingSoon: true },
    {
      label: "Graphics Design",
      href: "/services/graphics-design",
      comingSoon: true,
    },
  ],
  resources: [
    { label: "Blog", href: "/blog" },
    { label: "Careers", href: "/careers" },
  ],
  help: [
    { label: "Contact Us", href: "/contact" },
    { label: "Terms of Service", href: "/terms-of-service" },
    { label: "Privacy Policy", href: "/privacy-policy" },
  ],
};

const socialLinks = [
  { icon: Linkedin, href: SITE_CONFIG.social.linkedin, label: "LinkedIn" },
  { icon: Instagram, href: SITE_CONFIG.social.instagram, label: "Instagram" },
  { icon: Facebook, href: SITE_CONFIG.social.facebook, label: "Facebook" },
];

export function Footer() {
  return (
    <footer className="bg-brand-navy text-white">
      {/* Newsletter Section */}
      <div className="border-b border-white/10">
        <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8">
          <NewsletterSignup variant="dark" />
        </div>
      </div>

      {/* Links Grid */}
      <div className="mx-auto max-w-7xl px-4 py-12 sm:px-6 lg:px-8">
        <div className="grid grid-cols-2 gap-8 md:grid-cols-4">
          <FooterColumn title="About" links={footerLinks.about} />
          <FooterColumn title="Services" links={footerLinks.services} />
          <FooterColumn title="Resources" links={footerLinks.resources} />
          <FooterColumn title="Help" links={footerLinks.help} />
        </div>
      </div>

      {/* Bottom Bar */}
      <div className="border-t border-white/10">
        <div className="mx-auto flex max-w-7xl flex-col items-center justify-between gap-4 px-4 py-6 sm:flex-row sm:px-6 lg:px-8">
          <div className="flex items-center gap-4">
            <span className="text-lg font-bold">Boldteq</span>
            <span className="text-sm text-white/60">
              Designed with love from India
            </span>
          </div>

          <div className="flex items-center gap-4">
            {socialLinks.map(({ icon: Icon, href, label }) => (
              <Link
                key={label}
                href={href}
                target="_blank"
                rel="noopener noreferrer"
                className="text-white/60 transition-colors hover:text-white"
                aria-label={label}
              >
                <Icon className="h-5 w-5" />
              </Link>
            ))}
          </div>

          <p className="text-sm text-white/60">
            &copy; {new Date().getFullYear()} Boldteq. All rights reserved.
          </p>
        </div>
      </div>
    </footer>
  );
}

function FooterColumn({
  title,
  links,
}: {
  title: string;
  links: Array<{ label: string; href: string; comingSoon?: boolean }>;
}) {
  return (
    <div>
      <h3 className="mb-4 text-sm font-semibold uppercase tracking-wider text-white/80">
        {title}
      </h3>
      <ul className="space-y-3">
        {links.map((link) => (
          <li key={link.href}>
            <Link
              href={link.href}
              className="flex items-center gap-2 text-sm text-white/60 transition-colors hover:text-white"
            >
              {link.label}
              {link.comingSoon && (
                <span className="rounded-full bg-white/10 px-2 py-0.5 text-[10px]">
                  Soon
                </span>
              )}
            </Link>
          </li>
        ))}
      </ul>
    </div>
  );
}

